#!/usr/bin/env python3
"""
Attrium ArrayList Scissor & ClickGUI Bind Fixer (Fabric 1.21.11)
- Fixes ArrayListModule double-translated enableScissor clipping off-screen in 1.21.11.
- Registers ClientTickEvents.END_CLIENT_TICK in ClientModInitializer to guarantee ClickGUI bind
  polling runs every tick from frame 1 (zero dependency on mixins).
- Ensures InGameHudMixin & TickPipelineMixin are both present in mixins.json.
"""
import base64
import json
import os
import re
import sys

FILES_B64 = {
    "attrium/ru/api/module/impl/visual/ArrayListModule.java": "",
    "attrium/ru/manager/HudManager.java": "",
    "attrium/ru/screens/GlassClickGuiScreen.java": "",
    "attrium/ru/mixin/InGameHudMixin.java": "",
    "attrium/ru/mixin/TickPipelineMixin.java": "",

}


def ensure_mixins_registered(cwd):
    res_dir = os.path.join(cwd, "src", "main", "resources")
    if not os.path.isdir(res_dir):
        return
    for root, _, files in os.walk(res_dir):
        for fn in files:
            if fn.endswith("mixins.json"):
                path = os.path.join(root, fn)
                try:
                    with open(path, "r", encoding="utf-8") as f:
                        data = json.load(f)
                    key = "client" if "client" in data and isinstance(data["client"], list) else "mixins"
                    if key not in data or not isinstance(data[key], list):
                        data[key] = []
                    changed = False
                    for m in ("InGameHudMixin", "TickPipelineMixin"):
                        if m not in data[key]:
                            data[key].append(m)
                            changed = True
                            print(f"[MIXIN] Added {m} to {os.path.relpath(path, cwd)} ({key})")
                    if changed:
                        with open(path, "w", encoding="utf-8") as f:
                            json.dump(data, f, indent=2)
                except Exception as e:
                    print(f"[WARN] Could not update {fn}: {e}")


def wire_fabric_client_tick(src_root):
    for root, _, files in os.walk(src_root):
        for fn in files:
            if not fn.endswith(".java"):
                continue
            path = os.path.join(root, fn)
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                src = f.read()
            if "implements ClientModInitializer" not in src or "void onInitializeClient()" not in src:
                continue
            if "GlassClickGuiScreen.pollGlobalKeybinds()" in src:
                print(f"[OK] Fabric ClientTickEvents already wired in {os.path.relpath(path, src_root)}")
                return
            if "import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;" not in src:
                src = re.sub(
                    r"(package\s+[^;]+;\s*\n)",
                    r"\1import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;\nimport attrium.ru.screens.GlassClickGuiScreen;\n",
                    src,
                    count=1,
                )
            src = re.sub(
                r"(public\s+void\s+onInitializeClient\s*\(\s*\)\s*\{)",
                r"\1\n        ClientTickEvents.END_CLIENT_TICK.register(client -> GlassClickGuiScreen.pollGlobalKeybinds());",
                src,
                count=1,
            )
            with open(path, "w", encoding="utf-8") as f:
                f.write(src)
            print(f"[WIRED] Added Fabric ClientTickEvents ClickGUI keybind poll in {os.path.relpath(path, src_root)}")
            return
    print("[INFO] No ClientModInitializer found; relying on TickPipelineMixin + InGameHudMixin.")


def main():
    cwd = os.getcwd()
    src_root = os.path.join(cwd, "src", "main", "java")
    if not os.path.isdir(src_root):
        print(f"[ERROR] Run this script from your project root (missing {src_root}).")
        sys.exit(1)
    for rel_path, b64_data in FILES_B64.items():
        out_path = os.path.join(src_root, *rel_path.split("/"))
        os.makedirs(os.path.dirname(out_path), exist_ok=True)
        with open(out_path, "wb") as f:
            f.write(base64.b64decode(b64_data))
        print(f"[OK] Wrote {rel_path}")
    ensure_mixins_registered(cwd)
    wire_fabric_client_tick(src_root)
    print("\nArrayList & ClickGUI bind fix applied! Run: ./gradlew build --no-daemon")


if __name__ == "__main__":
    main()